Definition depot_avoid (W : list ivl) (d : depot) : Prop :=
  avoids W 2160280 (6354600 + 8) /\ avoids W 2094728 (2094728 + 28)
  /\ avoids W (d_nb d) (d_nb d + 16 * 65536) /\ avoids W (d_sb d) (d_sb d + 8 * 262144).
